function qsParse(qs){
  if(!qs) return {};
  if(qs.charAt(0)==='?') qs=qs.slice(1);
  var out={};
  var pairs=qs.split('&');
  for(var i=0;i<pairs.length;i++){
    if(pairs[i]==='') continue;
    var eq=pairs[i].indexOf('=');
    var k, v;
    if(eq<0){ k=pairs[i]; v=''; }
    else { k=pairs[i].slice(0,eq); v=pairs[i].slice(eq+1); }
    k=decodeURIComponent(k.replace(/\+/g,' '));
    v=decodeURIComponent(v.replace(/\+/g,' '));
    if(k in out){ if(Array.isArray(out[k])) out[k].push(v); else out[k]=[out[k], v]; }
    else out[k]=v;
  }
  return out;
}
function qsStringify(obj){
  var parts=[];
  for(var k in obj){
    if(!obj.hasOwnProperty(k)) continue;
    var v=obj[k];
    if(Array.isArray(v)){ for(var i=0;i<v.length;i++) parts.push(encodeURIComponent(k)+'='+encodeURIComponent(v[i])); }
    else parts.push(encodeURIComponent(k)+'='+encodeURIComponent(v));
  }
  return parts.join('&');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { qsParse:qsParse, qsStringify:qsStringify };
}
if (typeof window !== 'undefined') {
  window.QsForgePure = { qsParse:qsParse, qsStringify:qsStringify };
}
